export const driversScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}, x: string[] = []): string => `<script>
document.getElementById('addDriverBtn').addEventListener('click', function () {
  document.getElementById('driverModalTitle').textContent = 'Add Driver';
  document.getElementById('driverId').value = '';
  document.getElementById('driverName').value = '';
  document.getElementById('driverMobile').value = '';
  document.getElementById('driverVehicle').value = '';
  document.getElementById('driverArea').value = '';
  document.getElementById('driverActive').checked = true;
});
document.querySelectorAll('.edit-driver-btn').forEach(function (btn) {
  btn.addEventListener('click', function () {
    document.getElementById('driverModalTitle').textContent = 'Edit Driver';
    document.getElementById('driverId').value = btn.dataset.id;
    document.getElementById('driverName').value = btn.dataset.name;
    document.getElementById('driverMobile').value = btn.dataset.mobile;
    document.getElementById('driverVehicle').value = btn.dataset.vehicle;
    document.getElementById('driverArea').value = btn.dataset.area;
    document.getElementById('driverActive').checked = btn.dataset.active === '1';
  });
});
</script>`;
export const slipScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}, x: string[] = []): string => `<script>
// Same optional Local Print Service integration as modules/barcode/tags_print.php. No
// pairing/token step needed.
(function () {
  const BASE = 'http://127.0.0.1:9294';
  fetch(BASE + '/printers')
    .then(r => r.ok ? r.json() : Promise.reject())
    .then(data => {
      if (!data.success || !data.printers || !data.printers.length) return;
      const sel = document.getElementById('localPrintPrinter');
      data.printers.forEach(function (name) {
        const opt = document.createElement('option');
        opt.value = name; opt.textContent = name;
        if (name === data.defaultPrinter) opt.selected = true;
        sel.appendChild(opt);
      });
      document.getElementById('localPrintWrap').style.display = '';
    })
    .catch(function () {});

  document.getElementById('localPrintBtn')?.addEventListener('click', function () {
    const btn = this;
    btn.disabled = true; btn.textContent = 'Printing…';
    fetch(BASE + '/print', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ html: '<!DOCTYPE html>\\n' + document.documentElement.outerHTML, printerName: document.getElementById('localPrintPrinter').value, copies: 1 }),
    })
      .then(r => r.json())
      .then(function (result) {
        btn.disabled = false; btn.textContent = 'Print via Local Service';
        if (!result.success) alert('Print failed: ' + (result.message || result.error));
      })
      .catch(function () {
        btn.disabled = false; btn.textContent = 'Print via Local Service';
        alert('Could not reach the Local Print Service.');
      });
  });
})();
</script>`;
